// ── PERFUME · learn ─────────────────────────────────────────────────────────
const PERFUME_LEARN = [
  { id: "edp-vs-edt", ic: "🧪", title: "Eau de Parfum vs Eau de Toilette",
    desc: "The difference is concentration, and it changes more than longevity.",
    body: ["The names describe how much fragrance oil is dissolved in alcohol. Roughly: parfum 20–30%, eau de parfum 15–20%, eau de toilette 5–15%, eau de cologne 2–4%.",
      "Higher concentration means longer wear and closer projection. But it isn't simply 'more of the same scent' — the same fragrance in EDT and EDP is often reformulated, usually with the EDT brighter at the top and the EDP heavier at the base.",
      "If you love a fragrance in one concentration, sample the other before assuming it's identical."],
    note: "For office or daytime, an EDT is often the better choice — not because it's cheaper, but because it sits closer to the skin." },
  { id: "smells-different", ic: "🧬", title: "Why perfume smells different on everyone",
    desc: "Skin chemistry is real, and it's mostly about oil and pH.",
    body: ["Skin pH, oil production, diet, medication and hormones all influence how fragrance molecules evaporate and which notes dominate.",
      "Oilier skin holds fragrance longer and tends to amplify base notes — the woods, amber and musk. Drier skin lets top notes flash off quickly, so the same perfume can smell sharper and shorter.",
      "This is why testing on a paper strip tells you almost nothing about how it will wear on you."],
    note: "Hormonal changes in pregnancy genuinely alter how fragrance smells and how strongly you perceive it. Favourites can become intolerable, and that usually reverses." },
  { id: "notes-pyramid", ic: "🔺", title: "Top, middle and base notes",
    desc: "A fragrance is three stages, not one smell.",
    body: ["Top notes are the lightest molecules and evaporate first — usually citrus and herbs, lasting fifteen minutes to an hour. This is what you smell in the shop.",
      "Middle or heart notes emerge as the top fades — florals and spices, lasting two to four hours. This is the fragrance's actual character.",
      "Base notes are the heaviest and last longest — woods, musk, amber, vanilla — anywhere from four hours to the whole day.",
      "Judging a fragrance in the first ten minutes means judging a stage you'll barely wear."],
    note: "Always test on skin and wait at least half an hour before deciding. Most regretted purchases are top-note purchases." },
  { id: "nose-blind", ic: "👃", title: "Nose blindness",
    desc: "Why you stop smelling your own perfume, and why that isn't a reason to add more.",
    body: ["Olfactory adaptation is your brain filtering out a constant, unchanging signal so it can notice new ones. It happens within minutes and it's completely normal.",
      "Everyone else still smells it perfectly well. This is the single most common cause of over-application.",
      "Sniffing coffee beans between fragrances is a shop ritual more than a science — smelling your own skin, or simply stepping outside for a minute, resets you about as well."],
    note: "If you can smell your own perfume all day, you're almost certainly wearing too much. Two sprays is plenty for most EDPs." },
  { id: "last-longer", ic: "⏳", title: "Making fragrance last longer",
    desc: "Everything that works, ranked by how much it actually helps.",
    body: ["Moisturise first — the single biggest factor, and free.",
      "Spray onto warm pulse points, not clothing. Fabric holds scent but doesn't let it develop, and some fragrances stain.",
      "Layer with the matching body product if one exists. This is what fragrance houses design for, and it works.",
      "Choose a higher concentration. An EDP will simply outlast an EDT.",
      "What doesn't work: rubbing it in, spraying more, or spraying into the air and walking through it."],
    note: "If nothing makes a fragrance last, it may simply be a top-note-heavy composition. That's the perfume, not you." },
  { id: "concentration", ic: "📊", title: "Fragrance concentration explained",
    desc: "What you're paying for, in plain terms.",
    body: ["The price of a fragrance reflects concentration, the cost of the raw materials, and the brand. Only the first two affect what's in the bottle.",
      "Natural materials like oud, iris and real rose absolute are genuinely expensive — iris butter is among the costliest ingredients in perfumery. Synthetics aren't inferior; many are more stable, more consistent and kinder to the environment than harvesting the natural equivalent.",
      "A well-made synthetic fragrance can outperform a poorly blended natural one. 'All natural' is not a quality marker in perfumery."],
    note: "Buy the smallest size of anything new. A 30ml bottle you finish is a better purchase than a 100ml you tire of." },
]


